294	    /** A share percent as typed: up to two decimals. */
295	    private static final Pattern SHARE = Pattern.compile("\\d{1,3}(\\.\\d{1,2})?");
296	    private static final BigDecimal HUNDRED = new BigDecimal("100.00");
297	    /** How many pools deep a chain of pools may go. */
298	    private static final int MAX_DEPTH = 3;
299	
300	    private final PoolRepository pools;
301	    private final PersonRepository people;
302	    private final SheetService sheets;
303	    private final SheetRepository sheetRows;
