306	    public PoolService(PoolRepository pools, PersonRepository people, SheetService sheets, SheetRepository sheetRows,
307	            Audit audit) {
308	        this.pools = pools;
309	        this.people = people;
310	        this.sheets = sheets;
311	        this.sheetRows = sheetRows;
312	        this.audit = audit;
313	    }
314	
315	    /** The sheet's pools in the order they were added, each with its members. */
316	    @Transactional(readOnly = true)
317	    public List<Pool> list(String sheetId) {
318	        return pools.findBySheetIdOrderByIdAsc(sheetId);
319	    }
320	
321	    /** Add a pool under its name (trimmed), refused when it is blank or the sheet has a pool of that name. */
322	    @Transactional
323	    public Pool add(String sheetId, String user, String name) {
324	        String key = name == null ? "" : name.trim();
325	        if (key.isEmpty()) {
326	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "Type a pool name.");
327	        }
328	        sheets.load(sheetId);
329	        sheetRows.findForUpdate(sheetId);
330	        if (pools.existsBySheetIdAndName(sheetId, key)) throw alreadyPool(key);
331	        Pool saved;
332	        try {
333	            saved = pools.saveAndFlush(new Pool(sheetId, key));
334	        } catch (DataIntegrityViolationException raced) {
335	            throw alreadyPool(key);
336	        }
337	        audit.recordOnCommit("POOL_ADDED sheet=" + sheetId + " by=" + user + " name=" + saved.getName());
338	        return saved;
339	    }
340	
341	    /** Add a person of the sheet to a pool with a share percent of up to two decimals, more than 0.00
342	     *  and at most 100.00; refused when the person is already in the pool. */
343	    @Transactional
344	    public Pool addMember(String sheetId, String user, long poolId, long personId, String share) {
345	        BigDecimal value = shareOf(share);
346	        sheets.load(sheetId);
347	        sheetRows.findForUpdate(sheetId);
348	        Pool pool = poolOf(sheetId, poolId);
349	        Person person = people.findByIdAndSheetId(personId, sheetId)
350	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
351	                        "Choose a person of the sheet."));
352	        if (pool.hasMember(personId)) {
353	            throw new ResponseStatusException(HttpStatus.CONFLICT,
354	                    person.getName() + " is already in the pool " + pool.getName() + ".");
355	        }
356	        pool.addMember(personId, value);
357	        pool = pools.saveAndFlush(pool);
358	        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " pool=" + pool.getName()
359	                + " name=" + person.getName() + " share=" + value.toPlainString());
360	        return pool;
361	    }
362	
363	    /** Add another pool of the sheet to a pool with a share as for a person; refused when it is the pool
364	     *  itself, is already a member of a pool, contains the pool through any chain, or would make a chain of
365	     *  pools more than {@value #MAX_DEPTH} deep. */
366	    @Transactional
367	    public Pool addMemberPool(String sheetId, String user, long poolId, long memberPoolId, String share) {
368	        BigDecimal value = shareOf(share);
369	        sheets.load(sheetId);
370	        sheetRows.findForUpdate(sheetId);
371	        Pool pool = poolOf(sheetId, poolId);
372	        Pool member = pools.findById(memberPoolId).filter((p) -> p.getSheetId().equals(sheetId))
373	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
374	                        "Choose a pool of the sheet."));
375	        List<Pool> all = pools.findBySheetIdOrderByIdAsc(sheetId);
376	        Map<Long, Pool> parentOf = new HashMap<>();
377	        for (Pool p : all) {
378	            for (PoolMember m : p.getMembers()) {
379	                if (m.getMemberPoolId() != null) parentOf.put(m.getMemberPoolId(), p);
380	            }
381	        }
382	        if (member.getId().equals(pool.getId())) {
383	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A pool cannot be a member of itself.");
384	        }
385	        Pool parent = parentOf.get(member.getId());
386	        if (parent != null) {
387	            throw new ResponseStatusException(HttpStatus.CONFLICT,
388	                    "The pool " + member.getName() + " is already a member of the pool " + parent.getName() + ".");
389	        }
390	        int above = 1;
391	        for (Pool p = pool; parentOf.containsKey(p.getId()); p = parentOf.get(p.getId())) {
392	            if (parentOf.get(p.getId()).getId().equals(member.getId())) {
393	                throw new ResponseStatusException(HttpStatus.CONFLICT,
394	                        "The pool " + member.getName() + " contains the pool " + pool.getName() + ".");
395	            }
396	            above++;
397	        }
398	        Map<Long, Pool> byId = new HashMap<>();
399	        all.forEach((p) -> byId.put(p.getId(), p));
400	        if (above + depthOf(member, byId) > MAX_DEPTH) {
401	            throw new ResponseStatusException(HttpStatus.CONFLICT,
402	                    "A chain of pools may be at most " + MAX_DEPTH + " deep.");
403	        }
404	        pool.addMemberPool(member.getId(), value);
405	        try {
406	            pool = pools.saveAndFlush(pool);
407	        } catch (DataIntegrityViolationException raced) {
408	            throw new ResponseStatusException(HttpStatus.CONFLICT,
409	                    "The pool " + member.getName() + " is already a member of a pool.");
410	        }
411	        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " pool=" + pool.getName()
412	                + " name=" + member.getName() + " share=" + value.toPlainString());
413	        return pool;
414	    }
415	
416	    /** How many pools deep the pool's chains go: 1 with no member pools. */
417	    private static int depthOf(Pool pool, Map<Long, Pool> byId) {
418	        int deepest = 0;
419	        for (PoolMember m : pool.getMembers()) {
420	            if (m.getMemberPoolId() != null && byId.containsKey(m.getMemberPoolId())) {
421	                deepest = Math.max(deepest, depthOf(byId.get(m.getMemberPoolId()), byId));
422	            }
423	        }
424	        return deepest + 1;
425	    }
426	
427	    private Pool poolOf(String sheetId, long poolId) {
428	        return pools.findById(poolId).filter((p) -> p.getSheetId().equals(sheetId))
429	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such pool."));
430	    }
431	
432	    /** A share as typed: up to two decimals, more than 0.00 and at most 100.00. */
433	    private static BigDecimal shareOf(String share) {
434	        String typed = share == null ? "" : share.trim();
435	        if (!SHARE.matcher(typed).matches() || new BigDecimal(typed).signum() <= 0
436	                || new BigDecimal(typed).compareTo(HUNDRED) > 0) {
437	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
438	                    "Type a share of more than 0.00 and at most 100.00, with up to two decimals.");
439	        }
440	        return new BigDecimal(typed).setScale(2);
441	    }
442	
443	    private static ResponseStatusException alreadyPool(String name) {
444	        return new ResponseStatusException(HttpStatus.CONFLICT, "The sheet already has a pool \"" + name + "\".");
445	    }
446	}
