675	    if (!sheet) return;
676	    this.error.set('');
677	    const pool = this.pool();
678	    const { personId, share } = this.form.getRawValue();
679	    const typed = share.trim();
680	    if (personId === '') {
681	      this.error.set('Choose a person or pool.');
682	      return;
683	    }
684	    const memberPoolId = personId.startsWith(POOL_VALUE) ? Number(personId.slice(POOL_VALUE.length)) : null;
685	    if (memberPoolId === null && this.pool().members.some((m) => String(m.personId) === personId)) {
686	      this.error.set('That person is already in the pool.');
687	      return;
688	    }
689	    const refusal = memberPoolId === null ? '' : this.poolRefusal(memberPoolId);
690	    if (refusal) {
691	      this.error.set(refusal);
692	      return;
693	    }
694	    if (!SHARE.test(typed) || cents(typed) <= 0 || cents(typed) > 10000) {
695	      this.error.set('Type a share of more than 0.00 and at most 100.00, with up to two decimals.');
696	      return;
697	    }
698	    this.saving.set(true);
699	    try {
700	      await this.store.addMember(sheet.id, pool.id,
701	        memberPoolId === null ? { personId: Number(personId) } : { poolId: memberPoolId }, typed);
702	      if (this.session.sheet()?.id === sheet.id) this.form.reset({ personId: '', share: '' }, { emitEvent: false });
703	    } catch (e) {
704	      if (this.session.sheet()?.id !== sheet.id) return;
705	      const status = e instanceof HttpErrorResponse ? e.status : 0;
706	      this.error.set(status === 403 ? 'Your role may not change a pool on this sheet.'
707	        : status === 409 ? (memberPoolId === null ? 'That person is already in the pool.' : 'That pool cannot be added to this pool.')
708	        : status === 422 ? 'Type a share of more than 0.00 and at most 100.00, with up to two decimals.'
709	        : 'The member could not be added.');
710	    } finally {
711	      this.saving.set(false);
712	    }
713	  }
714	
715	  /** Why the pool may not be added as a member of this one, or blank. */
716	  private poolRefusal(memberPoolId: number): string {
717	    const pool = this.pool();
718	    const member = this.poolsById().get(memberPoolId);
719	    if (!member) return 'Choose a pool of the sheet.';
720	    if (member.id === pool.id) return 'A pool cannot be a member of itself.';
721	    const parents = parentsOf(this.pools());
722	    const parent = parents.get(member.id);
723	    if (parent) return `The pool ${member.name} is already a member of the pool ${parent.name}.`;
724	    let above = 1;
725	    for (let p = parents.get(pool.id); p; p = parents.get(p.id)) {
726	      if (p.id === member.id) return `The pool ${member.name} contains the pool ${pool.name}.`;
727	      if (++above > MAX_DEPTH) break;
728	    }
729	    if (above + depthOf(member, this.poolsById()) > MAX_DEPTH) return `A chain of pools may be at most ${MAX_DEPTH} deep.`;
730	    return '';
731	  }
732	}
733	
734	/** The pool's members as the screens show them. */
735	function membersOf(pool: PoolView, people: readonly PersonView[], poolsById: ReadonlyMap<number, PoolView>,
736	    today?: string): MemberRow[] {
737	  const peopleById = new Map(people.map((p) => [p.id, p]));
738	  return pool.members.map((m) => {
739	    const person = m.personId !== null ? peopleById.get(m.personId) : undefined;
740	    const name = m.personId !== null ? (person?.name ?? '') : `pool:${poolsById.get(m.poolId ?? -1)?.name ?? ''}`;
741	    const held = person !== undefined && today !== undefined && heldOn(person.holds, today);
742	    return { key: memberKey(m, poolsById), share: m.share, name, retired: person?.retired ?? false, held };
743	  });
744	}
745	
746	/** The members' shares added up, in cents; a retired member's counts as 0. */
747	function totalCents(members: readonly MemberRow[]): number {
748	  return members.reduce((t, m) => (m.retired ? t : t + cents(m.share)), 0);
749	}
750	
751	/** Each pool's cuts by member key, by pool id: null for an unbalanced pool or one with no pot. A pool that
752	 *  is a member of none has the sheet's pot; one that is a member of another has its cut there. */
753	function allCuts(pools: readonly PoolView[], people: readonly PersonView[], pot: string | null,
754	    today: string | undefined): Map<number, Map<string, bigint> | null> {
755	  const poolsById = new Map(pools.map((p) => [p.id, p]));
756	  const parents = parentsOf(pools);
757	  const out = new Map<number, Map<string, bigint> | null>();
758	  const cutsFor = (pool: PoolView, depth: number): Map<string, bigint> | null => {
759	    if (out.has(pool.id)) return out.get(pool.id) ?? null;
760	    out.set(pool.id, null);
761	    let potCents: bigint | null = null;
762	    const parent = parents.get(pool.id);
763	    if (!parent) potCents = pot === null ? null : BigInt(cents(pot));
764	    else if (depth <= pools.length) potCents = cutsFor(parent, depth + 1)?.get(`pool-${pool.name}`) ?? null;
765	    const members = membersOf(pool, people, poolsById, today);
766	    const result = potCents === null || totalCents(members) !== 10000 ? null : new Map(cutsOf(potCents, members));
767	    out.set(pool.id, result);
768	    return result;
769	  };
770	  pools.forEach((p) => cutsFor(p, 0));
771	  return out;
772	}
773	
774	/** Each person's cut total in cents, by person id: their cuts across every pool they are a member of added
775	 *  up; a pool that shows no cuts adds nothing. */
776	export function personCutTotals(pools: readonly PoolView[], people: readonly PersonView[], pot: string | null,
777	    today: string | undefined): Map<number, number> {
778	  const cuts = allCuts(pools, people, pot, today);
779	  const totals = new Map<number, number>();
780	  for (const pool of pools) {
781	    const poolCuts = cuts.get(pool.id);
782	    if (!poolCuts) continue;
783	    for (const m of pool.members) {
784	      if (m.personId === null) continue;
785	      totals.set(m.personId, (totals.get(m.personId) ?? 0) + Number(poolCuts.get(String(m.personId)) ?? 0n));
786	    }
787	  }
788	  return totals;
789	}
790	
791	/** A whole number divided by another, rounded half to even. */
792	function divideHalfEven(value: bigint, by: bigint): bigint {
793	  const quotient = value / by;
794	  const twice = 2n * (value % by);
795	  return twice > by || (twice === by && quotient % 2n !== 0n) ? quotient + 1n : quotient;
796	}
797	
798	/** The cuts of a pot (in cents) among members in the order they were added, by person: each the pot times
799	 *  their share over the shares of the members with a cut added up, half to even (a retired or held
800	 *  member's 0); the remainder to the largest share with a cut, the earliest added on a tie. With no
801	 *  member with a cut, every cut is 0. */
802	function cutsOf(potCents: bigint, members: readonly MemberRow[]): [string, bigint][] {
803	  const shares = members.map((m) => (m.retired || m.held ? 0 : cents(m.share)));
804	  const total = BigInt(shares.reduce((t, share) => t + share, 0));
805	  const cuts = shares.map((share) => (total === 0n ? 0n : divideHalfEven(potCents * BigInt(share), total)));
806	  let largest = 0;
807	  shares.forEach((share, i) => {
808	    if (share > shares[largest]) largest = i;
809	  });
810	  if (total > 0n) cuts[largest] += potCents - cuts.reduce((t, c) => t + c, 0n);
811	  return members.map((m, i) => [m.key, cuts[i]]);
812	}
813	
814	// The sheet's pools, with a form to add one.
815	@Component({
816	  selector: 'app-pools',
817	  imports: [ReactiveFormsModule, PoolRow],
818	  template: `
819	    <section aria-labelledby="pools-heading">
820	      <h2 id="pools-heading">Pools</h2>
821	      <form [formGroup]="form" (ngSubmit)="submit()" aria-label="Add a pool">
822	        <label for="pool-form-name">Name</label>
823	        <input id="pool-form-name" data-testid="pool-form-name" formControlName="name" />
824	        <button type="submit" data-testid="pool-form-submit" [disabled]="saving()">Add pool</button>
825	        @if (error() || store.loadError(); as message) {
826	          <p role="alert" data-testid="pool-form-error">{{ message }}</p>
827	        }
828	      </form>
829	      <div role="list" aria-label="Pools">
830	        @for (p of store.pools(); track p.id) {
831	          <app-pool-row [pool]="p" [people]="people()" [pools]="store.pools()" [cuts]="cuts().get(p.id) ?? null" />
832	        }
833	      </div>
834	    </section>
835	  `,
836	})
837	export class PoolsList {
838	  private readonly session = inject(Session);
839	  protected readonly store = inject(Pools);
840	  private readonly sheetPot = inject(SheetPot);
841	
842	  /** Everyone on the sheet, retired or not. */
843	  readonly people = input.required<PersonView[]>();
844	
845	  /** Each pool's cuts, with two decimals, by member key, by pool id. */
846	  protected readonly cuts = computed(() => new Map([...allCuts(this.store.pools(), this.people(), this.sheetPot.pot(),
847	    this.session.sheet()?.today)]
848	    .map(([id, cuts]) => [id, cuts && new Map([...cuts].map(([key, cut]) => [key, money(Number(cut))]))])));
849	
850	  protected readonly name = new FormControl('', { nonNullable: true });
851	  protected readonly form = new FormGroup({ name: this.name });
852	  protected readonly saving = signal(false);
853	  protected readonly error = signal('');
854	
855	  constructor() {
856	    this.form.valueChanges.subscribe(() => this.error.set(''));
857	  }
858	
859	  protected async submit(): Promise<void> {
860	    if (this.saving()) return;
861	    const sheet = this.session.sheet();
862	    if (!sheet) return;
863	    this.error.set('');
864	    const name = this.name.value.trim();
865	    if (name === '') {
866	      this.error.set('Type a pool name.');
867	      return;
868	    }
869	    if (this.store.pools().some((p) => p.name === name)) {
870	      this.error.set(`The sheet already has a pool "${name}".`);
871	      return;
872	    }
873	    this.saving.set(true);
874	    try {
875	      await this.store.add(sheet.id, name);
876	      if (this.session.sheet()?.id === sheet.id) this.form.reset({ name: '' }, { emitEvent: false });
877	    } catch (e) {
878	      if (this.session.sheet()?.id !== sheet.id) return;
879	      const status = e instanceof HttpErrorResponse ? e.status : 0;
880	      this.error.set(status === 403 ? 'Your role may not add a pool on this sheet.'
881	        : status === 409 ? `The sheet already has a pool "${name}".`
882	        : status === 422 ? 'Type a pool name.'
883	        : 'The pool could not be added.');
884	    } finally {
885	      this.saving.set(false);
886	    }
887	  }
888	}
