package net.officefloor.hq.app.pool;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import java.util.List;
import net.officefloor.hq.app.SignedInUser;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/sheets/{sheetId}/pools")
@Validated
public class PoolController {

    /** A member of a pool as the screen shows it: a person or a pool (the other id null); the share always
     *  has two decimals. */
    public record MemberView(Long personId, Long poolId, String share) {
        static MemberView of(PoolMember member) {
            return new MemberView(member.getPersonId(), member.getMemberPoolId(), member.getShare().toPlainString());
        }
    }

    /** What the screen shows of a pool: its name and its members in the order they were added. */
    public record PoolView(long id, String name, List<MemberView> members) {
        static PoolView of(Pool pool) {
            return new PoolView(pool.getId(), pool.getName(), pool.getMembers().stream().map(MemberView::of).toList());
        }
    }

    public record PoolForm(@Size(max = 200) String name) {
    }

    /** A member to add: a person of the sheet or another pool of it (exactly one), and its share as typed. */
    public record MemberForm(Long personId, Long poolId, @Size(max = 30) String share) {
    }

    private final PoolService service;

    public PoolController(PoolService service) {
        this.service = service;
    }

    /** The sheet's pools in the order they were added. */
    @GetMapping
    public List<PoolView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        return service.list(sheetId.trim()).stream().map(PoolView::of).toList();
    }

    /** Add a pool. */
    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PoolView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid PoolForm form) {
        return PoolView.of(service.add(sheetId.trim(), SignedInUser.name(user), form.name()));
    }

    /** Add a member to a pool: the pool as it is then. */
    @PostMapping("/{poolId}/members")
    public PoolView addMember(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long poolId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid MemberForm form) {
        if ((form.personId() == null) == (form.poolId() == null)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "Choose a person or a pool.");
        }
        String by = SignedInUser.name(user);
        return PoolView.of(form.personId() != null
                ? service.addMember(sheetId.trim(), by, poolId, form.personId(), form.share())
                : service.addMemberPool(sheetId.trim(), by, poolId, form.poolId(), form.share()));
    }
}
package net.officefloor.hq.app.pool;

import jakarta.persistence.CascadeType;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OneToMany;
import jakarta.persistence.OrderBy;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;

/** A pool of the sheet: a name and its members, each a person with a share percent. */
@Entity
@Table(name = "pool")
public class Pool {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    /** The members in the order they were added. */
    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
    @JoinColumn(name = "pool_id", nullable = false)
    @OrderBy("id ASC")
    private List<PoolMember> members = new ArrayList<>();

    protected Pool() {
    }

    public Pool(String sheetId, String name) {
        this.sheetId = sheetId;
        this.name = name;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public List<PoolMember> getMembers() {
        return List.copyOf(members);
    }

    /** Whether the person is a member of the pool. */
    public boolean hasMember(long personId) {
        return members.stream().anyMatch((m) -> m.isPerson(personId));
    }

    /** Give a member's place in the pool to another person: added to that person's share when they are
     *  already a member (held to 100.00), else taken over by them; nothing when the member is not in it. */
    public void moveMember(long fromPersonId, long intoPersonId) {
        PoolMember from = memberOf(fromPersonId);
        if (from == null) return;
        PoolMember into = memberOf(intoPersonId);
        if (into == null) {
            from.setPersonId(intoPersonId);
        } else {
            into.addShare(from.getShare());
            members.remove(from);
        }
    }

    /** Take the person out of the pool; nothing when they are not in it. */
    public void removeMember(long personId) {
        members.removeIf((m) -> m.isPerson(personId));
    }

    private PoolMember memberOf(long personId) {
        return members.stream().filter((m) -> m.isPerson(personId)).findFirst().orElse(null);
    }

    /** Whether the pool is a member of this one. */
    public boolean hasMemberPool(long poolId) {
        return members.stream().anyMatch((m) -> m.getMemberPoolId() != null && m.getMemberPoolId() == poolId);
    }

    /** Add the person with a share (kept to two decimals). */
    public void addMember(long personId, BigDecimal share) {
        members.add(new PoolMember(personId, null, share));
    }

    /** Add another pool as a member with a share (kept to two decimals). */
    public void addMemberPool(long poolId, BigDecimal share) {
        members.add(new PoolMember(null, poolId, share));
    }
}
package net.officefloor.hq.app.pool;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;

/** A member of a pool, a person or another pool of the sheet, with its share percent of it. */
@Entity
@Table(name = "pool_member")
public class PoolMember {

    private static final BigDecimal HUNDRED = new BigDecimal("100.00");

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /** The person, or null when the member is a pool. */
    @Column(name = "person_id")
    private Long personId;

    /** The pool, or null when the member is a person. */
    @Column(name = "member_pool_id")
    private Long memberPoolId;

    @Column(name = "share", nullable = false, precision = 5, scale = 2)
    private BigDecimal share;

    protected PoolMember() {
    }

    PoolMember(Long personId, Long memberPoolId, BigDecimal share) {
        this.personId = personId;
        this.memberPoolId = memberPoolId;
        this.share = share.setScale(2);
    }

    void setPersonId(long personId) {
        this.personId = personId;
    }

    /** Add to the share, held to at most 100.00. */
    void addShare(BigDecimal more) {
        BigDecimal sum = share.add(more);
        share = sum.compareTo(HUNDRED) > 0 ? HUNDRED : sum;
    }

    public Long getId() {
        return id;
    }

    /** The person, or null when the member is a pool. */
    public Long getPersonId() {
        return personId;
    }

    /** The pool, or null when the member is a person. */
    public Long getMemberPoolId() {
        return memberPoolId;
    }

    boolean isPerson(long id) {
        return personId != null && personId == id;
    }

    public BigDecimal getShare() {
        return share;
    }
}
package net.officefloor.hq.app.pool;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface PoolRepository extends JpaRepository<Pool, Long> {

    /** The sheet's pools in the order they were added. */
    List<Pool> findBySheetIdOrderByIdAsc(String sheetId);

    Optional<Pool> findBySheetIdAndName(String sheetId, String name);

    boolean existsBySheetIdAndName(String sheetId, String name);
}
package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class PoolService {

    /** A share percent as typed: up to two decimals. */
    private static final Pattern SHARE = Pattern.compile("\\d{1,3}(\\.\\d{1,2})?");
    private static final BigDecimal HUNDRED = new BigDecimal("100.00");
    /** How many pools deep a chain of pools may go. */
    private static final int MAX_DEPTH = 3;

    private final PoolRepository pools;
    private final PersonRepository people;
    private final SheetService sheets;
    private final SheetRepository sheetRows;
    private final Audit audit;

    public PoolService(PoolRepository pools, PersonRepository people, SheetService sheets, SheetRepository sheetRows,
            Audit audit) {
        this.pools = pools;
        this.people = people;
        this.sheets = sheets;
        this.sheetRows = sheetRows;
        this.audit = audit;
    }

    /** The sheet's pools in the order they were added, each with its members. */
    @Transactional(readOnly = true)
    public List<Pool> list(String sheetId) {
        return pools.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Add a pool under its name (trimmed), refused when it is blank or the sheet has a pool of that name. */
    @Transactional
    public Pool add(String sheetId, String user, String name) {
        String key = name == null ? "" : name.trim();
        if (key.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "Type a pool name.");
        }
        sheets.load(sheetId);
        sheetRows.findForUpdate(sheetId);
        if (pools.existsBySheetIdAndName(sheetId, key)) throw alreadyPool(key);
        Pool saved;
        try {
            saved = pools.saveAndFlush(new Pool(sheetId, key));
        } catch (DataIntegrityViolationException raced) {
            throw alreadyPool(key);
        }
        audit.recordOnCommit("POOL_ADDED sheet=" + sheetId + " by=" + user + " name=" + saved.getName());
        return saved;
    }

    /** Add a person of the sheet to a pool with a share percent of up to two decimals, more than 0.00
     *  and at most 100.00; refused when the person is already in the pool. */
    @Transactional
    public Pool addMember(String sheetId, String user, long poolId, long personId, String share) {
        BigDecimal value = shareOf(share);
        sheets.load(sheetId);
        sheetRows.findForUpdate(sheetId);
        Pool pool = poolOf(sheetId, poolId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
                        "Choose a person of the sheet."));
        if (pool.hasMember(personId)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    person.getName() + " is already in the pool " + pool.getName() + ".");
        }
        pool.addMember(personId, value);
        pool = pools.saveAndFlush(pool);
        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " pool=" + pool.getName()
                + " name=" + person.getName() + " share=" + value.toPlainString());
        return pool;
    }

    /** Add another pool of the sheet to a pool with a share as for a person; refused when it is the pool
     *  itself, is already a member of a pool, contains the pool through any chain, or would make a chain of
     *  pools more than {@value #MAX_DEPTH} deep. */
    @Transactional
    public Pool addMemberPool(String sheetId, String user, long poolId, long memberPoolId, String share) {
        BigDecimal value = shareOf(share);
        sheets.load(sheetId);
        sheetRows.findForUpdate(sheetId);
        Pool pool = poolOf(sheetId, poolId);
        Pool member = pools.findById(memberPoolId).filter((p) -> p.getSheetId().equals(sheetId))
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
                        "Choose a pool of the sheet."));
        List<Pool> all = pools.findBySheetIdOrderByIdAsc(sheetId);
        Map<Long, Pool> parentOf = new HashMap<>();
        for (Pool p : all) {
            for (PoolMember m : p.getMembers()) {
                if (m.getMemberPoolId() != null) parentOf.put(m.getMemberPoolId(), p);
            }
        }
        if (member.getId().equals(pool.getId())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A pool cannot be a member of itself.");
        }
        Pool parent = parentOf.get(member.getId());
